<boltAction type="file" filePath="src/lib/coralred-storage.js">const CLOUD_API_BASE = import.meta.env.VITE_CLOUD_API_BASE || '';
const CLOUD_APP_TOKEN = import.meta.env.VITE_CLOUD_APP_TOKEN || '';
const CLOUD_ENABLED = Boolean(CLOUD_API_BASE && CLOUD_APP_TOKEN);

export const isCloudStorageEnabled = CLOUD_ENABLED;

const DEVICE_KEY_STORAGE_KEY = 'coralred_cloud_device_key';
let memoryDeviceKey = null;

function getDeviceKey() {
  try {
    let key = localStorage.getItem(DEVICE_KEY_STORAGE_KEY);

    if (!key) {
      key = crypto.randomUUID();
      localStorage.setItem(DEVICE_KEY_STORAGE_KEY, key);
    }

    return key;
  } catch {
    if (!memoryDeviceKey) {
      memoryDeviceKey = crypto.randomUUID();
    }

    return memoryDeviceKey;
  }
}

const memoryStore = new Map();

function memoryCollection(collection) {
  if (!memoryStore.has(collection)) {
    memoryStore.set(collection, new Map());
  }

  return memoryStore.get(collection);
}

function nowIso() {
  return new Date().toISOString();
}

export class CoralredStorageError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'CoralredStorageError';
    this.status = status;
  }
}

function mapErrorMessage(status) {
  if (status === 401 || status === 403) {
    return '저장 기능 연결에 문제가 있어요. 다시 배포해보세요.';
  }

  if (status === 404) {
    return '찾을 수 없어요.';
  }

  if (status === 413) {
    return '저장할 내용이 너무 커요.';
  }

  if (status === 429) {
    return '요청이 너무 많아요. 잠시 후 다시 시도해주세요.';
  }

  if (status === 507) {
    return '저장 공간이 다 찼어요. 요금제를 확인해주세요.';
  }

  return '저장하다가 문제가 생겼어요. 잠시 후 다시 시도해주세요.';
}

async function request(method, pathSuffix, body) {
  const url = `${CLOUD_API_BASE}/${pathSuffix}`;

  let response;

  try {
    response = await fetch(url, {
      method,
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${CLOUD_APP_TOKEN}`,
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch {
    throw new CoralredStorageError('네트워크 문제로 저장하지 못했어요. 잠시 후 다시 시도해주세요.', 0);
  }

  if (!response.ok) {
    let message = mapErrorMessage(response.status);

    try {
      const errorBody = await response.json();

      if (errorBody && typeof errorBody.error === 'string') {
        message = errorBody.error;
      }
    } catch {
      // 응답 본문이 JSON이 아닐 수 있음 — 상태코드 기반 기본 메시지를 그대로 씀.
    }

    throw new CoralredStorageError(message, response.status);
  }

  if (response.status === 204) {
    return null;
  }

  return response.json();
}

export const db = {
  async create(collection, data) {
    const deviceKey = getDeviceKey();

    if (!CLOUD_ENABLED) {
      const id = crypto.randomUUID();
      const doc = { id, data, createdAt: nowIso(), updatedAt: nowIso() };
      memoryCollection(collection).set(id, doc);

      return doc;
    }

    return request('POST', collection, { deviceKey, data });
  },

  async list(collection, options) {
    const deviceKey = getDeviceKey();
    const limit = (options && options.limit) || 20;

    if (!CLOUD_ENABLED) {
      const all = Array.from(memoryCollection(collection).values()).sort((a, b) =>
        a.createdAt < b.createdAt ? 1 : -1,
      );

      return { items: all.slice(0, limit), nextCursor: null };
    }

    const params = new URLSearchParams({ deviceKey, limit: String(limit) });

    if (options && options.cursor) {
      params.set('cursor', options.cursor);
    }

    return request('GET', `${collection}?${params.toString()}`);
  },

  async get(collection, id) {
    const deviceKey = getDeviceKey();

    if (!CLOUD_ENABLED) {
      const doc = memoryCollection(collection).get(id);

      if (!doc) {
        throw new CoralredStorageError('찾을 수 없어요.', 404);
      }

      return doc;
    }

    return request('GET', `${collection}/${encodeURIComponent(id)}?deviceKey=${encodeURIComponent(deviceKey)}`);
  },

  async update(collection, id, data) {
    const deviceKey = getDeviceKey();

    if (!CLOUD_ENABLED) {
      const coll = memoryCollection(collection);
      const existing = coll.get(id);

      if (!existing) {
        throw new CoralredStorageError('찾을 수 없어요.', 404);
      }

      const updated = { ...existing, data, updatedAt: nowIso() };
      coll.set(id, updated);

      return updated;
    }

    return request('PATCH', `${collection}/${encodeURIComponent(id)}`, { deviceKey, data });
  },

  async remove(collection, id) {
    const deviceKey = getDeviceKey();

    if (!CLOUD_ENABLED) {
      memoryCollection(collection).delete(id);
      return null;
    }

    return request('DELETE', `${collection}/${encodeURIComponent(id)}?deviceKey=${encodeURIComponent(deviceKey)}`);
  },
};
</boltAction>

<boltAction type="file" filePath="src/lib/reservations.js">import { db } from './coralred-storage.js';

export const SERVICE_OPTIONS = ['커트', '펌', '염색', '클리닉', '드라이', '업스타일'];

export const STATUS = {
  CONFIRMED: 'confirmed',
  PENDING: 'pending',
  CANCELED: 'canceled',
  DONE: 'done',
};

export const STATUS_LABEL = {
  [STATUS.CONFIRMED]: '확정',
  [STATUS.PENDING]: '대기',
  [STATUS.CANCELED]: '취소',
  [STATUS.DONE]: '완료',
};

function pad(n) {
  return String(n).padStart(2, '0');
}

export function toDateKey(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

export function formatDateLabel(dateKey) {
  const d = new Date(`${dateKey}T00:00:00`);
  const days = ['일', '월', '화', '수', '목', '금', '토'];
  return `${d.getMonth() + 1}월 ${d.getDate()}일 (${days[d.getDay()]})`;
}

export function buildSampleReservations() {
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);
  const lastWeekBase = new Date(today);
  lastWeekBase.setDate(today.getDate() - 7);

  const todayKey = toDateKey(today);
  const tomorrowKey = toDateKey(tomorrow);

  const names = ['김지은', '박서연', '이하윤', '최민준', '정도윤', '한유진', '오세라', '윤지호', '장하은', '조은서', '배수민', '신재원'];
  const phones = ['010-2231-8845', '010-9912-3341', '010-5567-2210', '010-8823-9910', '010-1123-5567', '010-6634-8821', '010-3345-1120', '010-7723-9081', '010-4451-2290', '010-9012-3345', '010-2245-7781', '010-5591-2231'];

  const items = [];

  const todaySlots = [
    { start: '10:00', end: '11:00', service: '커트', status: STATUS.CONFIRMED },
    { start: '11:30', end: '13:30', service: '펌', status: STATUS.CONFIRMED },
    { start: '14:00', end: '16:00', service: '염색', status: STATUS.CONFIRMED },
    { start: '16:30', end: '17:00', service: '드라이', status: STATUS.PENDING },
    { start: '17:30', end: '18:30', service: '클리닉', status: STATUS.CONFIRMED },
  ];

  todaySlots.forEach((slot, i) => {
    items.push({
      customerName: names[i],
      phone: phones[i],
      dateKey: todayKey,
      startTime: slot.start,
      endTime: slot.end,
      service: slot.service,
      status: slot.status,
      memo: '',
    });
  });

  const tomorrowSlots = [
    { start: '10:30', end: '11:30', service: '커트', status: STATUS.CONFIRMED },
    { start: '13:00', end: '13:30', service: '드라이', status: STATUS.PENDING },
    { start: '15:00', end: '17:00', service: '업스타일', status: STATUS.CANCELED },
  ];

  tomorrowSlots.forEach((slot, i) => {
    items.push({
      customerName: names[5 + i],
      phone: phones[5 + i],
      dateKey: tomorrowKey,
      startTime: slot.start,
      endTime: slot.end,
      service: slot.service,
      status: slot.status,
      memo: '',
    });
  });

  const lastWeekSlots = [
    { offset: 0, start: '11:00', end: '12:00', service: '커트' },
    { offset: 1, start: '14:00', end: '15:30', service: '펌' },
    { offset: 2, start: '10:00', end: '12:00', service: '염색' },
    { offset: 3, start: '16:00', end: '16:30', service: '드라이' },
  ];

  lastWeekSlots.forEach((slot, i) => {
    const d = new Date(lastWeekBase);
    d.setDate(lastWeekBase.getDate() + slot.offset);
    items.push({
      customerName: names[8 + i] || names[i],
      phone: phones[8 + i] || phones[i],
      dateKey: toDateKey(d),
      startTime: slot.start,
      endTime: slot.end,
      service: slot.service,
      status: STATUS.DONE,
      memo: '',
    });
  });

  return items;
}

export async function seedIfEmpty() {
  const { items } = await db.list('reservations', { limit: 100 });

  if (items.length > 0) {
    return items;
  }

  const sample = buildSampleReservations();
  const created = [];

  for (const data of sample) {
    const doc = await db.create('reservations', data);
    created.push(doc);
  }

  return created;
}
</boltAction>

<boltAction type="file" filePath="src/components/BottomNav.tsx">import { Home, CalendarDays, Plus } from 'lucide-react';

type Tab = 'home' | 'calendar' | 'new';

interface Props {
  active: Tab;
  onChange: (tab: Tab) => void;
}

export default function BottomNav({ active, onChange }: Props) {
  const items: { key: Tab; label: string; icon: typeof Home }[] = [
    { key: 'home', label: '홈', icon: Home },
    { key: 'calendar', label: '날짜별 보기', icon: CalendarDays },
    { key: 'new', label: '예약 등록', icon: Plus },
  ];

  return (
    <nav
      className="cr-row-8"
      style={{
        position: 'fixed',
        bottom: 0,
        left: 0,
        right: 0,
        background: 'var(--surface)',
        borderTop: '1px solid var(--border)',
        padding: '8px 16px calc(8px + env(safe-area-inset-bottom))',
        justifyContent: 'space-around',
        zIndex: 20,
      }}
    >
      {items.map(({ key, label, icon: Icon }) => (
        <button
          key={key}
          type="button"
          onClick={() => onChange(key)}
