          <Icon size={20} strokeWidth={1.5} />
          <span className="cr-caption" style={{ color: 'inherit' }}>
            {label}
          </span>
        </button>
      ))}
    </nav>
  );
}
</boltAction>

<boltAction type="file" filePath="src/components/StatusBadge.tsx">import { STATUS, STATUS_LABEL } from '../lib/reservations.js';

export default function StatusBadge({ status }: { status: string }) {
  const cls =
    status === STATUS.CONFIRMED
      ? 'cr-badge ok'
      : status === STATUS.PENDING
        ? 'cr-badge warn'
        : status === STATUS.CANCELED
          ? 'cr-badge err'
          : 'cr-badge';

  return <span className={cls}>{STATUS_LABEL[status] || status}</span>;
}
</boltAction>

<boltAction type="file" filePath="src/components/ReservationCard.tsx">import { Clock, Scissors } from 'lucide-react';
import StatusBadge from './StatusBadge';

interface Reservation {
  id: string;
  data: {
    customerName: string;
    phone: string;
    startTime: string;
    endTime: string;
    service: string;
    status: string;
  };
}

interface Props {
  reservation: Reservation;
  onClick?: () => void;
}

export default function ReservationCard({ reservation, onClick }: Props) {
  const { customerName, startTime, endTime, service, status } = reservation.data;

  return (
    <button
      type="button"
      onClick={onClick}
      className="cr-card cr-stack-8"
      style={{
        width: '100%',
        textAlign: 'left',
        cursor: onClick ? 'pointer' : 'default',
        padding: '16px',
        transition: 'background-color 180ms ease-out, transform 180ms ease-out',
      }}
      onMouseEnter={(e) => {
