          <span className="cr-caption">{service}</span>
        </div>
        <span className="cr-body">{customerName}</span>
      </div>
    </button>
  );
}
</boltAction>

<boltAction type="file" filePath="src/pages/HomePage.tsx">import { useMemo } from 'react';
import { CalendarCheck, Clock3 } from 'lucide-react';
import ReservationCard from '../components/ReservationCard';
import { toDateKey, formatDateLabel, STATUS } from '../lib/reservations.js';

interface Reservation {
  id: string;
  data: {
    customerName: string;
    phone: string;
    dateKey: string;
    startTime: string;
    endTime: string;
    service: string;
    status: string;
    memo: string;
  };
}

interface Props {
  reservations: Reservation[];
  loading: boolean;
  onSelect: (r: Reservation) => void;
}

const BUSINESS_START = 10 * 60;
const BUSINESS_END = 20 * 60;

function toMinutes(time: string) {
  const [h, m] = time.split(':').map(Number);
  return h * 60 + m;
}

export default function HomePage({ reservations, loading, onSelect }: Props) {
  const todayKey = toDateKey(new Date());

  const todayItems = useMemo(
    () =>
      reservations
        .filter((r) => r.data.dateKey === todayKey && r.data.status !== STATUS.CANCELED)
        .sort((a, b) => a.data.startTime.localeCompare(b.data.startTime)),
    [reservations, todayKey],
  );

  const activeCount = todayItems.filter((r) => r.data.status !== STATUS.DONE).length;

  const freeMinutes = useMemo(() => {
    const busy = todayItems
      .filter((r) => r.data.status !== STATUS.CANCELED)
      .map((r) => [toMinutes(r.data.startTime), toMinutes(r.data.endTime)] as [number, number])
      .sort((a, b) => a[0] - b[0]);

    let free = 0;
    let cursor = BUSINESS_START;

    for (const [start, end] of busy) {
      if (start > cursor) {
        free += start - cursor;
      }
      cursor = Math.max(cursor, end);
    }

    if (cursor < BUSINESS_END) {
      free += BUSINESS_END - cursor;
    }

    return free;
  }, [todayItems]);

  const freeHours = Math.floor(freeMinutes / 60);
  const freeMinsRest = freeMinutes % 60;

  if (loading) {
    return (
      <div className="cr-page">
        <section className="cr-section cr-stack-16">
          <div className="cr-grid-2">
            <div className="cr-card" style={{ height: '96px' }} />
            <div className="cr-card" style={{ height: '96px' }} />
          </div>
        </section>
      </div>
    );
  }

  return (
    <div className="cr-page" style={{ paddingBottom: '96px' }}>
      <section className="cr-section cr-stack-24">
        <div className="cr-stack-4">
          <span className="cr-eyebrow">헤어살롱 예약 관리</span>
          <h1 className="cr-h1">{formatDateLabel(todayKey)}</h1>
        </div>

        <div className="cr-grid-2">
          <div className="cr-card cr-stack-8">
            <div className="cr-row-8" style={{ alignItems: 'center' }}>
              <CalendarCheck size={18} strokeWidth={1.5} style={{ color: 'var(--accent)' }} />
              <span className="cr-caption">오늘 예약</span>
            </div>
            <span className="cr-display">{activeCount}건</span>
          </div>
          <div className="cr-card cr-stack-8">
            <div className="cr-row-8" style={{ alignItems: 'center' }}>
              <Clock3 size={18} strokeWidth={1.5} style={{ color: 'var(--muted)' }} />
              <span className="cr-caption">남은 빈 시간</span>
            </div>
            <span className="cr-display">
              {freeHours}시간 {freeMinsRest > 0 ? `${freeMinsRest}분` : ''}
            </span>
          </div>
        </div>

        <div className="cr-stack-16">
          <h2 className="cr-h2">오늘 타임라인</h2>
          {todayItems.length === 0 ? (
            <div className="cr-card cr-stack-8" style={{ textAlign: 'center', padding: '32px 16px' }}>
              <span className="cr-body">오늘 예약이 아직 없어요</span>
              <span className="cr-caption">예약 등록 탭에서 새 예약을 추가해보세요</span>
            </div>
          ) : (
            <div className="cr-stack-8">
              {todayItems.map((r) => (
                <ReservationCard key={r.id} reservation={r} onClick={() => onSelect(r)} />
              ))}
            </div>
          )}
        </div>
      </section>
    </div>
  );
}
</boltAction>

<boltAction type="file" filePath="src/pages/CalendarPage.tsx">import { useMemo, useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import ReservationCard from '../components/ReservationCard';
import { toDateKey, STATUS } from '../lib/reservations.js';

interface Reservation {
  id: string;
  data: {
    customerName: string;
    phone: string;
    dateKey: string;
    startTime: string;
    endTime: string;
    service: string;
    status: string;
    memo: string;
  };
}

interface Props {
  reservations: Reservation[];
  loading: boolean;
  onSelect: (r: Reservation) => void;
}

function startOfWeek(date: Date) {
  const d = new Date(date);
  const day = d.getDay();
  d.setDate(d.getDate() - day);
  d.setHours(0, 0, 0, 0);
  return d;
}

export default function CalendarPage({ reservations, loading, onSelect }: Props) {
  const [weekStart, setWeekStart] = useState(() => startOfWeek(new Date()));
  const [selectedKey, setSelectedKey] = useState(() => toDateKey(new Date()));

  const days = useMemo(() => {
    return Array.from({ length: 7 }, (_, i) => {
      const d = new Date(weekStart);
      d.setDate(weekStart.getDate() + i);
      return d;
    });
  }, [weekStart]);

  const countsByDay = useMemo(() => {
    const map = new Map<string, number>();
    for (const r of reservations) {
      if (r.data.status === STATUS.CANCELED) continue;
      const key = r.data.dateKey;
      map.set(key, (map.get(key) || 0) + 1);
    }
    return map;
  }, [reservations]);

  const dayLabels = ['일', '월', '화', '수', '목', '금', '토'];

  const selectedItems = useMemo(
    () =>
      reservations
        .filter((r) => r.data.dateKey === selectedKey)
        .sort((a, b) => a.data.startTime.localeCompare(b.data.startTime)),
    [reservations, selectedKey],
  );

  if (loading) {
    return (
      <div className="cr-page">
        <section className="cr-section">
          <div className="cr-card" style={{ height: '200px' }} />
        </section>
      </div>
    );
  }

  return (
    <div className="cr-page" style={{ paddingBottom: '96px' }}>
      <section className="cr-section cr-stack-24">
        <div className="cr-stack-4">
          <span className="cr-eyebrow">날짜별 보기</span>
          <h1 className="cr-h1">주간 예약 현황</h1>
        </div>

        <div className="cr-row-8" style={{ justifyContent: 'space-between', alignItems: 'center' }}>
          <button
            type="button"
            className="cr-btn outline"
            style={{ padding: '8px', minWidth: '44px' }}
            onClick={() => {
              const d = new Date(weekStart);
              d.setDate(d.getDate() - 7);
              setWeekStart(d);
            }}
          >
            <ChevronLeft size={16} />
          </button>
          <span className="cr-body" style={{ fontWeight: 600 }}>
            {days[0].getMonth() + 1}월 {days[0].getDate()}일 - {days[6].getMonth() + 1}월{' '}
            {days[6].getDate()}일
          </span>
          <button
            type="button"
            className="cr-btn outline"
            style={{ padding: '8px', minWidth: '44px' }}
            onClick={() => {
              const d = new Date(weekStart);
