<boltAction type="file" filePath="src/pages/NewReservationPage.tsx">import { useState, FormEvent } from 'react';
import { CalendarPlus } from 'lucide-react';
import { SERVICE_OPTIONS, STATUS, toDateKey } from '../lib/reservations.js';

interface Props {
  onCreate: (data: {
    customerName: string;
    phone: string;
    dateKey: string;
    startTime: string;
    endTime: string;
    service: string;
    status: string;
    memo: string;
  }) => Promise<void>;
}

export default function NewReservationPage({ onCreate }: Props) {
  const [customerName, setCustomerName] = useState('');
  const [phone, setPhone] = useState('');
  const [dateKey, setDateKey] = useState(toDateKey(new Date()));
  const [startTime, setStartTime] = useState('10:00');
  const [endTime, setEndTime] = useState('11:00');
  const [service, setService] = useState(SERVICE_OPTIONS[0]);
  const [memo, setMemo] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [toast, setToast] = useState('');

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();

    if (!customerName.trim() || !phone.trim()) {
      setToast('예약자 이름과 연락처를 입력해주세요');
      setTimeout(() => setToast(''), 2000);
      return;
    }

    if (startTime >= endTime) {
      setToast('종료 시각은 시작 시각보다 늦어야 해요');
      setTimeout(() => setToast(''), 2000);
      return;
    }

    setSubmitting(true);

    try {
      await onCreate({
        customerName: customerName.trim(),
        phone: phone.trim(),
        dateKey,
        startTime,
        endTime,
        service,
        status: STATUS.CONFIRMED,
        memo: memo.trim(),
      });

      setCustomerName('');
      setPhone('');
      setMemo('');
      setToast('예약이 등록됐어요');
      setTimeout(() => setToast(''), 2000);
    } catch (err) {
      setToast(err instanceof Error ? err.message : '등록하다가 문제가 생겼어요');
      setTimeout(() => setToast(''), 2500);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="cr-page" style={{ paddingBottom: '96px' }}>
      <section className="cr-section cr-stack-24">
        <div className="cr-stack-4">
          <span className="cr-eyebrow">새 예약</span>
          <h1 className="cr-h1">예약 등록하기</h1>
        </div>

        <form onSubmit={handleSubmit} className="cr-stack-16">
          <div className="cr-stack-8">
            <label className="cr-label" htmlFor="customerName">
              예약자 이름
            </label>
            <input
              id="customerName"
              className="cr-input"
              placeholder="예: 김지은"
              value={customerName}
              onChange={(e) => setCustomerName(e.target.value)}
            />
          </div>

          <div className="cr-stack-8">
            <label className="cr-label" htmlFor="phone">
              연락처
            </label>
            <input
              id="phone"
              className="cr-input"
              placeholder="010-0000-0000"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
            />
          </div>

          <div className="cr-stack-8">
            <label className="cr-label" htmlFor="dateKey">
              예약 날짜
            </label>
            <input
              id="dateKey"
              type="date"
              className="cr-input"
              value={dateKey}
              onChange={(e) => setDateKey(e.target.value)}
            />
          </div>

          <div className="cr-grid-2">
            <div className="cr-stack-8">
              <label className="cr-label" htmlFor="startTime">
                시작 시각
              </label>
              <input
                id="startTime"
                type="time"
                className="cr-input"
                value={startTime}
                onChange={(e) => setStartTime(e.target.value)}
              />
            </div>
            <div className="cr-stack-8">
              <label className="cr-label" htmlFor="endTime">
                종료 시각
              </label>
              <input
                id="endTime"
                type="time"
                className="cr-input"
                value={endTime}
                onChange={(e) => setEndTime(e.target.value)}
              />
            </div>
          </div>

          <div className="cr-stack-8">
            <label className="cr-label" htmlFor="service">
              시술 항목
            </label>
            <select
              id="service"
              className="cr-input"
              value={service}
              onChange={(e) => setService(e.target.value)}
            >
              {SERVICE_OPTIONS.map((opt) => (
                <option key={opt} value={opt}>
                  {opt}
                </option>
              ))}
            </select>
          </div>

          <div className="cr-stack-8">
            <label className="cr-label" htmlFor="memo">
              메모 (선택)
            </label>
            <textarea
              id="memo"
              className="cr-input"
              placeholder="요청 사항이 있다면 적어주세요"
              value={memo}
              onChange={(e) => setMemo(e.target.value)}
              rows={3}
            />
          </div>

          <button type="submit" className="cr-btn" disabled={submitting} style={{ width: '100%' }}>
            <CalendarPlus size={16} />
            {submitting ? '등록 중...' : '예약 등록하기'}
          </button>
        </form>

        {toast && (
          <div
            className="cr-badge ok"
            style={{ position: 'fixed', bottom: '96px', left: '50%', transform: 'translateX(-50%)' }}
          >
            {toast}
          </div>
        )}
      </section>
    </div>
  );
}
