<boltAction type="file" filePath="src/App.tsx">import { useEffect, useState } from 'react';
import { db, isCloudStorageEnabled } from './lib/coralred-storage.js';
import { seedIfEmpty } from './lib/reservations.js';
import BottomNav from './components/BottomNav';
import HomePage from './pages/HomePage';
import CalendarPage from './pages/CalendarPage';
import NewReservationPage from './pages/NewReservationPage';
import ReservationDetailSheet from './components/ReservationDetailSheet';

type Tab = 'home' | 'calendar' | 'new';

interface Reservation {
  id: string;
  data: {
    customerName: string;
    phone: string;
    dateKey: string;
    startTime: string;
    endTime: string;
    service: string;
    status: string;
    memo: string;
  };
}

function App() {
  const [tab, setTab] = useState<Tab>('home');
  const [reservations, setReservations] = useState<Reservation[]>([]);
  const [loading, setLoading] = useState(true);
  const [selected, setSelected] = useState<Reservation | null>(null);

  useEffect(() => {
    let mounted = true;

    seedIfEmpty()
      .then((items) => {
        if (mounted) {
          setReservations(items as Reservation[]);
          setLoading(false);
        }
      })
      .catch(() => {
        if (mounted) {
          setLoading(false);
        }
      });

    return () => {
      mounted = false;
    };
  }, []);

  async function handleCreate(data: Reservation['data']) {
    const created = await db.create('reservations', data);
    setReservations((prev) => [created as Reservation, ...prev]);
    setTab('home');
  }

  async function handleStatusChange(id: string, status: string) {
    const target = reservations.find((r) => r.id === id);
    if (!target) return;

    const updated = await db.update('reservations', id, { ...target.data, status });
    setReservations((prev) => prev.map((r) => (r.id === id ? (updated as Reservation) : r)));
    setSelected(updated as Reservation);
  }

  return (
    <div style={{ minHeight: '100vh' }}>
      {!isCloudStorageEnabled && (
        <div style={{ position: 'sticky', top: 0, zIndex: 10, textAlign: 'center', padding: '8px 0', background: 'var(--bg)' }}>
          <span className="cr-badge warn">데이터가 이 기기에만 저장돼요</span>
        </div>
      )}

      {tab === 'home' && (
        <HomePage reservations={reservations} loading={loading} onSelect={setSelected} />
      )}
      {tab === 'calendar' && (
        <CalendarPage reservations={reservations} loading={loading} onSelect={setSelected} />
      )}
      {tab === 'new' && <NewReservationPage onCreate={handleCreate} />}

      {selected && (
        <ReservationDetailSheet
          reservation={selected}
          onClose={() => setSelected(null)}
          onStatusChange={handleStatusChange}
        />
      )}

      <BottomNav active={tab} onChange={setTab} />
    </div>
  );
}

export default App;
</boltAction>

