import { db } from './coralred-storage.js';

export const SERVICE_OPTIONS = ['커트', '펌', '염색', '클리닉', '드라이', '업스타일'];

export const STATUS = {
  CONFIRMED: 'confirmed',
  PENDING: 'pending',
  CANCELED: 'canceled',
  DONE: 'done',
};

export const STATUS_LABEL = {
  [STATUS.CONFIRMED]: '확정',
  [STATUS.PENDING]: '대기',
  [STATUS.CANCELED]: '취소',
  [STATUS.DONE]: '완료',
};

function pad(n) {
  return String(n).padStart(2, '0');
}

export function toDateKey(date) {
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

export function formatDateLabel(dateKey) {
  const d = new Date(`${dateKey}T00:00:00`);
  const days = ['일', '월', '화', '수', '목', '금', '토'];
  return `${d.getMonth() + 1}월 ${d.getDate()}일 (${days[d.getDay()]})`;
}

export function buildSampleReservations() {
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);
  const lastWeekBase = new Date(today);
  lastWeekBase.setDate(today.getDate() - 7);

  const todayKey = toDateKey(today);
  const tomorrowKey = toDateKey(tomorrow);

  const names = ['김지은', '박서연', '이하윤', '최민준', '정도윤', '한유진', '오세라', '윤지호', '장하은', '조은서', '배수민', '신재원'];
  const phones = ['010-2231-8845', '010-9912-3341', '010-5567-2210', '010-8823-9910', '010-1123-5567', '010-6634-8821', '010-3345-1120', '010-7723-9081', '010-4451-2290', '010-9012-3345', '010-2245-7781', '010-5591-2231'];

  const items = [];

  const todaySlots = [
    { start: '10:00', end: '11:00', service: '커트', status: STATUS.CONFIRMED },
    { start: '11:30', end: '13:30', service: '펌', status: STATUS.CONFIRMED },
    { start: '14:00', end: '16:00', service: '염색', status: STATUS.CONFIRMED },
    { start: '16:30', end: '17:00', service: '드라이', status: STATUS.PENDING },
    { start: '17:30', end: '18:30', service: '클리닉', status: STATUS.CONFIRMED },
  ];

  todaySlots.forEach((slot, i) => {
    items.push({
      customerName: names[i],
      phone: phones[i],
      dateKey: todayKey,
      startTime: slot.start,
      endTime: slot.end,
      service: slot.service,
      status: slot.status,
      memo: '',
    });
  });

  const tomorrowSlots = [
    { start: '10:30', end: '11:30', service: '커트', status: STATUS.CONFIRMED },
    { start: '13:00', end: '13:30', service: '드라이', status: STATUS.PENDING },
    { start: '15:00', end: '17:00', service: '업스타일', status: STATUS.CANCELED },
  ];

  tomorrowSlots.forEach((slot, i) => {
    items.push({
      customerName: names[5 + i],
      phone: phones[5 + i],
      dateKey: tomorrowKey,
      startTime: slot.start,
      endTime: slot.end,
      service: slot.service,
      status: slot.status,
      memo: '',
    });
  });

  const lastWeekSlots = [
    { offset: 0, start: '11:00', end: '12:00', service: '커트' },
    { offset: 1, start: '14:00', end: '15:30', service: '펌' },
    { offset: 2, start: '10:00', end: '12:00', service: '염색' },
    { offset: 3, start: '16:00', end: '16:30', service: '드라이' },
  ];

  lastWeekSlots.forEach((slot, i) => {
    const d = new Date(lastWeekBase);
    d.setDate(lastWeekBase.getDate() + slot.offset);
    items.push({
      customerName: names[8 + i] || names[i],
      phone: phones[8 + i] || phones[i],
      dateKey: toDateKey(d),
      startTime: slot.start,
      endTime: slot.end,
      service: slot.service,
      status: STATUS.DONE,
      memo: '',
    });
  });

  return items;
}

export async function seedIfEmpty() {
  const { items } = await db.list('reservations', { limit: 100 });

  if (items.length > 0) {
    return items;
  }

  const sample = buildSampleReservations();
  const created = [];

  for (const data of sample) {
    const doc = await db.create('reservations', data);
    created.push(doc);
  }

  return created;
}

