import { X, Phone, Calendar, Clock, Scissors } from 'lucide-react';
import { STATUS, STATUS_LABEL, formatDateLabel } from '../lib/reservations.js';
import StatusBadge from './StatusBadge';

interface Reservation {
  id: string;
  data: {
    customerName: string;
    phone: string;
    dateKey: string;
    startTime: string;
    endTime: string;
    service: string;
    status: string;
    memo: string;
  };
}

interface Props {
  reservation: Reservation;
  onClose: () => void;
  onStatusChange: (id: string, status: string) => Promise<void>;
}

export default function ReservationDetailSheet({ reservation, onClose, onStatusChange }: Props) {
  const { customerName, phone, dateKey, startTime, endTime, service, status, memo } = reservation.data;

  return (
    <div
      className="cr-overlay"
      style={{
        position: 'fixed',
        inset: 0,
        background: 'rgba(0,0,0,0.4)',
        display: 'flex',
        alignItems: 'flex-end',
        justifyContent: 'center',
        zIndex: 50,
      }}
      onClick={onClose}
    >
      <div
        className="cr-card cr-stack-16"
        style={{
          width: '100%',
          maxWidth: '480px',
          borderBottomLeftRadius: 0,
          borderBottomRightRadius: 0,
          padding: '24px',
          maxHeight: '80vh',
          overflowY: 'auto',
        }}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="cr-row-8" style={{ justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 className="cr-h2">예약 상세</h2>
          <button
            type="button"
            onClick={onClose}
            style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '8px', minWidth: '44px', minHeight: '44px' }}
          >
            <X size={20} strokeWidth={1.5} style={{ color: 'var(--muted)' }} />
          </button>
        </div>

        <div className="cr-row-8" style={{ alignItems: 'center', justifyContent: 'space-between' }}>
          <span className="cr-h1" style={{ fontSize: '20px' }}>
            {customerName}
          </span>
          <StatusBadge status={status} />
        </div>

        <div className="cr-stack-8">
          <div className="cr-row-8" style={{ alignItems: 'center' }}>
            <Phone size={16} strokeWidth={1.5} style={{ color: 'var(--muted)' }} />
            <span className="cr-body">{phone}</span>
          </div>
          <div className="cr-row-8" style={{ alignItems: 'center' }}>
            <Calendar size={16} strokeWidth={1.5} style={{ color: 'var(--muted)' }} />
            <span className="cr-body">{formatDateLabel(dateKey)}</span>
          </div>
          <div className="cr-row-8" style={{ alignItems: 'center' }}>
            <Clock size={16} strokeWidth={1.5} style={{ color: 'var(--muted)' }} />
            <span className="cr-body">
              {startTime} - {endTime}
            </span>
          </div>
          <div className="cr-row-8" style={{ alignItems: 'center' }}>
            <Scissors size={16} strokeWidth={1.5} style={{ color: 'var(--muted)' }} />
            <span className="cr-body">{service}</span>
          </div>
          {memo && (
            <div className="cr-card cr-stack-4" style={{ padding: '12px' }}>
              <span className="cr-caption">메모</span>
              <span className="cr-body">{memo}</span>
            </div>
          )}
        </div>

        <div className="cr-stack-8">
          <span className="cr-label">상태 변경</span>
          <div className="cr-row-8" style={{ flexWrap: 'wrap' }}>
            {Object.values(STATUS).map((s) => (
              <button
                key={s}
                type="button"
                className={s === status ? 'cr-btn' : 'cr-btn outline'}
                style={{ flex: '1 1 auto' }}
                onClick={() => onStatusChange(reservation.id, s)}
              >
                {STATUS_LABEL[s]}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
